아래는 실제 저장소의 draft shortlist 생성 코드입니다. 이를 재사용 가능한 순수 Python 함수 select_ids(valid, protected, freq, size)로 분리하려 합니다. 표준 라이브러리만 사용하세요. valid/protected는 정수 ID iterable, freq는 ID→빈도 mapping입니다. 입력은 수정하지 않습니다. valid 중 protected는 모두 포함하되 protected에 invalid ID가 하나라도 있으면 ValueError. size는 bool이 아닌 정수이며 len(protected) 이상 len(valid) 이하, 아니면 ValueError. 빈도는 양의 유한 실수만 사용하며 bool·NaN·inf·0·음수·invalid ID는 무시합니다. 나머지는 빈도 내림차순, 동률 ID 오름차순으로 선택하고 남는 자리는 valid ID 오름차순으로 채웁니다. 결과는 정렬된 list입니다. 원본의 연속 ID 가정을 제거하고 빈 valid/size=0도 처리하세요. 설명 대신 실행 가능한 함수와 필요한 import만 반환하세요.
원본:
#!/usr/bin/env python3
"""Build a TP1 draft shortlist from synthetic calibration output.

Keep all complete Hangul tokens and special tokens. Rank observed calibration
tokens by frequency, then fill by tokenizer ID. This changes drafting only.
Run inside the serving image (tokenizers and torch are already installed).
"""
import argparse
import collections
import hashlib
import json
import pathlib

from tokenizers import Tokenizer


def byte_decoder():
    bs = list(range(33, 127)) + list(range(161, 173)) + list(range(174, 256))
    cs = bs[:]
    extra = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256 + extra)
            extra += 1
    return {chr(c): b for b, c in zip(bs, cs)}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--tokenizer", required=True)
    ap.add_argument("--corpus", required=True)
    ap.add_argument("--output", required=True)
    ap.add_argument("--size", type=int, default=65536)
    ap.add_argument("--verify", help="held-out result JSON; reports coverage only")
    args = ap.parse_args()
    raw = pathlib.Path(args.tokenizer).read_bytes()
    data = json.loads(raw)
    tokenizer = Tokenizer.from_file(args.tokenizer)
    inverse = byte_decoder()
    protected = set(range(256)) | {v["id"] for v in data["added_tokens"]}
    hangul = set()
    for text, ident in data["model"]["vocab"].items():
        try:
            decoded = bytes(inverse[c] for c in text).decode("utf-8")
        except (KeyError, UnicodeDecodeError):
            continue
        if any("\uac00" <= c <= "\ud7a3" for c in decoded):
            hangul.add(ident)
    protected.update(hangul)
    freq = collections.Counter()
    corpus = json.loads(pathlib.Path(args.corpus).read_text())
    for row in corpus["rows"]:
        for field in ["prompt", "content"]:
            freq.update(tokenizer.encode(row[field], add_special_tokens=False).ids)
    chosen = set(protected)
    valid = set(tokenizer.get_vocab().values())
    if len(chosen) > args.size or args.size > len(valid):
        raise ValueError("size must fit protected tokens and tokenizer vocabulary")
    for ident in sorted(freq, key=lambda ident: (-freq[ident], ident)) + sorted(valid):
        if len(chosen) >= args.size:
            break
        chosen.add(ident)
    ids = sorted(chosen)
    ranges = []
    for ident in ids:
        if ranges and ident == ranges[-1][1]:
            ranges[-1][1] += 1
        else:
            ranges.append([ident, ident+1])
    def coverage(counts):
        return sum(n for ident, n in counts.items() if ident in chosen) / max(1, sum(counts.values()))
    result = dict(version=1, size=len(ids), tokenizer_sha256=hashlib.sha256(raw).hexdigest(),
                  corpus_sha256=hashlib.sha256(pathlib.Path(args.corpus).read_bytes()).hexdigest(),
                  policy="special + byte tokens + all complete Hangul tokens + corpus frequency + ascending ID fill",
                  protected_hangul=len(hangul), calibration_coverage=coverage(freq), ranges=ranges)
    if args.verify:
        by_category = {}
        for row in json.loads(pathlib.Path(args.verify).read_text())["rows"]:
            by_category.setdefault(row["name"], collections.Counter()).update(tokenizer.encode(row["content"], add_special_tokens=False).ids)
        result["held_out_coverage"] = {k: coverage(v) for k,v in by_category.items()}
    out = pathlib.Path(args.output)
    out.write_text(json.dumps(result, ensure_ascii=False, separators=(",", ":")) + "\n")
    import torch
    torch.save(ids, str(out.with_suffix(".pt")))
    assert len(ids) == args.size and len(set(ids)) == args.size and set(ids) <= valid
    print(json.dumps({k:v for k,v in result.items() if k != "ranges"}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

실제 HTML 수집기의 다음 코드를 리뷰하세요. 요구사항은 script/style/template 등 숨겨진 하위 트리의 텍스트뿐 아니라 링크와 표도 결과에 들어가지 않는 것입니다. 현재 hidden 처리만으로 충족되는지 제어 흐름을 따라 판단하고, 재현 HTML과 예상 결과, 수정 위치와 회귀 테스트를 제시하세요. 공개 링크/표 처리와 nested-table 문제를 구분하고 무관한 리팩터링은 피하세요. 한국어로 설명하고 필요한 Go 수정 부분을 보여 주세요.
package main

import (
	"archive/zip"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"path/filepath"
	"strings"
	"time"
	"unicode"

	"golang.org/x/net/html"
)

type manifest struct {
	Version      int       `json:"version"`
	RequestedURL string    `json:"requested_url"`
	FinalURL     string    `json:"final_url"`
	Title        string    `json:"title"`
	Method       string    `json:"method"`
	ContentType  string    `json:"content_type"`
	RawPath      string    `json:"raw_path"`
	FetchedAt    time.Time `json:"fetched_at"`
}

type linkRecord struct {
	Text string `json:"text"`
	URL  string `json:"url"`
}

type resourceRecord struct {
	URL      string `json:"url"`
	MIMEType string `json:"mime_type,omitempty"`
	Type     string `json:"type,omitempty"`
	Status   int64  `json:"status,omitempty"`
}

type collected struct {
	Manifest    manifest
	Raw         []byte
	Text        string
	Tables      [][][]string
	Links       []linkRecord
	Resources   []resourceRecord
	Publication *publicationPlan
	Screenshot  []byte
}

func normalizeHTML(data []byte, baseURL string) (string, string, [][][]string, []linkRecord, error) {
	document, err := html.Parse(bytes.NewReader(data))
	if err != nil {
		return "", "", nil, nil, err
	}
	base, _ := url.Parse(baseURL)
	title := ""
	var text strings.Builder
	links := []linkRecord{}
	tables := [][][]string{}
	var visit func(*html.Node, bool, bool)
	visit = func(node *html.Node, hidden, insideTable bool) {
		if node.Type == html.ElementNode {
			switch node.Data {
			case "script", "style", "noscript", "svg", "template":
				hidden = true
			case "table":
				if table := parseTable(node); len(table) > 0 {
					tables = append(tables, table)
				}
				insideTable = true
			case "a":
				if href := attribute(node, "href"); href != "" {
					if target, err := base.Parse(href); err == nil && (target.Scheme == "http" || target.Scheme == "https") {
						links = append(links, linkRecord{Text: compactText(nodeText(node)), URL: target.String()})
					}
				}
			}
		}
		if !hidden && !insideTable && node.Type == html.TextNode {
			value := compactText(node.Data)
			if value != "" {
				if node.Parent != nil && node.Parent.Type == html.ElementNode && node.Parent.Data == "title" {
					title = value
				}
				text.WriteString(value)
				text.WriteByte('\n')
			}
		}
		for child := node.FirstChild; child != nil; child = child.NextSibling {
			visit(child, hidden, insideTable)
		}
	}
	visit(document, false, false)
	for index, table := range tables {
		text.WriteString(fmt.Sprintf("\n[표 %d]\n", index+1))
		for _, row := range table {
			text.WriteString(strings.Join(row, " | "))
			text.WriteByte('\n')
		}
	}
	return title, strings.TrimSpace(text.String()), tables, dedupeLinks(links), nil
}

func parseTable(table *html.Node) [][]string {
	rows := [][]string{}
	var walk func(*html.Node)
	walk = func(node *html.Node) {
		if node.Type == html.ElementNode && node.Data == "tr" {
			row := []string{}
			for child := node.FirstChild; child != nil; child = child.NextSibling {
				if child.Type == html.ElementNode && (child.Data == "td" || child.Data == "th") {
					row = append(row, compactText(nodeText(child)))
				}
			}
			if len(row) > 0 {
				rows = append(rows, row)
			}
			return
		}
		for child := node.FirstChild; child != nil; child = child.NextSibling {
			walk(child)
		}
	}
	walk(table)
	return rows
}

func nodeText(node *html.Node) string {
	var output strings.Builder
	var walk func(*html.Node)
	walk = func(current *html.Node) {
		if current.Type == html.TextNode {
			output.WriteString(current.Data)
			output.WriteByte(' ')
		}
		for child := current.FirstChild; child != nil; child = child.NextSibling {
			walk(child)
		}
	}
	walk(node)
	return output.String()
}

func compactText(value string) string {
	return strings.Join(strings.Fields(value), " ")
}

func attribute(node *html.Node, name string) string {
	for _, attribute := range node.Attr {
		if attribute.Key == name {
			return strings.TrimSpace(attribute.Val)
		}
	}
	return ""
}

func dedupeLinks(items []linkRecord) []linkRecord {
	seen := make(map[string]struct{})
	result := make([]linkRecord, 0, len(items))
	for _, item := range items {
		if _, ok := seen[item.URL]; ok {
			continue
		}
		seen[item.URL] = struct{}{}
		result = append(result, item)
		if len(result) >= 2000 {
			break
		}
	}
	return result
}

func writeBundle(output io.Writer, item collected) error {
	archive := zip.NewWriter(output)
	write := func(name string, data []byte) error {
		header := &zip.FileHeader{Name: name, Method: zip.Deflate}
		header.SetModTime(item.Manifest.FetchedAt)
		part, err := archive.CreateHeader(header)
		if err != nil {
			return err
		}
		_, err = part.Write(data)
		return err
	}
	manifestData, _ := json.MarshalIndent(item.Manifest, "", "  ")
	if err := write("manifest.json", manifestData); err != nil {
		return err
	}
	if err := write(item.Manifest.RawPath, item.Raw); err != nil {
		return err
	}
	if item.Text != "" {
		if err := write("normalized/text.txt", []byte(item.Text)); err != nil {
			return err
		}
	}
	if len(item.Tables) > 0 {
		data, _ := json.MarshalIndent(item.Tables, "", "  ")
		if err := write("normalized/tables.json", data); err != nil {
			return err
		}
	}
	if len(item.Links) > 0 {
		data, _ := json.MarshalIndent(item.Links, "", "  ")
		if err := write("normalized/links.json", data); err != nil {
			return err
		}
	}
	if len(item.Resources) > 0 {
		data, _ := json.MarshalIndent(item.Resources, "", "  ")
		if err := write("normalized/resources.json", data); err != nil {
			return err
		}
	}
	if item.Publication != nil {
		data, _ := json.MarshalIndent(item.Publication, "", "  ")
		if err := write("normalized/publication.json", data); err != nil {
			return err
		}
	}
	if len(item.Screenshot) > 0 {
		if err := write("preview/screenshot.png", item.Screenshot); err != nil {
			return err
		}
	}
	return archive.Close()
}

func rawPath(rawURL, contentType string) string {
	extension := extensionForContentType(contentType)
	if parsed, err := url.Parse(rawURL); err == nil {
		if ext := filepath.Ext(parsed.Path); ext != "" && len(ext) <= 10 {
			extension = ext
		}
	}
	if extension == "" {
		extension = ".bin"
	}
	return "raw/source" + extension
}

func extensionForContentType(value string) string {
	value = strings.ToLower(strings.Split(value, ";")[0])
	switch value {
	case "text/html":
		return ".html"
	case "application/pdf":
		return ".pdf"
	case "application/json":
		return ".json"
	case "application/javascript", "application/x-javascript", "text/javascript":
		return ".js"
	case "text/csv":
		return ".csv"
	case "text/plain":
		return ".txt"
	case "application/xml", "text/xml":
		return ".xml"
	case "image/png":
		return ".png"
	case "image/jpeg":
		return ".jpg"
	case "image/webp":
		return ".webp"
	default:
		return ""
	}
}

func fallbackTitle(rawURL string) string {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return "수집 자료"
	}
	name := strings.TrimSpace(filepath.Base(parsed.Path))
	if name == "" || name == "." || name == "/" {
		name = parsed.Hostname()
	}
	if decoded, err := url.PathUnescape(name); err == nil {
		name = decoded
	}
	if name == "" {
		return "수집 자료"
	}
	return name
}

func bundleName(title string) string {
	title = strings.Map(func(char rune) rune {
		if char == '/' || char == '\\' || unicode.IsControl(char) {
			return -1
		}
		return char
	}, title)
	title = strings.TrimSpace(title)
	if title == "" {
		title = "collection"
	}
	return fmt.Sprintf("%s.zip", title)
}
